/**
 * scripts/lockscreen/designs.ts
 *
 * Side-effect-free module holding every Fiore Vera iPhone lock screen design
 * (1179×2556, iPhone 15/16 @3x). Nothing here is generated by an image model:
 * every layer is keyed and composited from existing painted / photographed
 * material in public/assets/lockscreen/.
 *
 * Inputs read (public/assets/lockscreen/):
 *   wreath-source.jpg           — painted rose + eucalyptus wreath on cream paper
 *   frame-gold.jpg              — slender carved gold frame on white (linen-classic, blush-minimal)
 *   ornate-frame.jpg            — baroque gold frame on white (ink-editorial)
 *   delicate-filigree-frame.jpg — openwork filigree frame on white (sage-garland)
 *   logo-badge.jpg              — Fiore Vera wordmark badge on white
 *
 * Designs:
 *   renderInkEditorial  — THE SHIPPED FINAL: ink background, wreath, ornate gold
 *                         frame glowing against the dark, QR on linen inside,
 *                         badge on a linen disc
 *   renderLinenClassic  — the previous final: linen + blush wash, wreath behind
 *                         the slender carved frame, badge multiplied below
 *   renderSageGarland   — sage background, wreath flopped and pushed low,
 *                         filigree frame on a linen card, badge above
 *   renderBlushMinimal  — blush→linen gradient, one rose cluster bleeding in
 *                         from the bottom-right corner, slender frame, small badge
 *
 * Each render takes the output path and the URL the QR should encode
 * (defaults to the website). Entry points: scripts/generate-lockscreen.ts and
 * scripts/generate-lockscreen-variants.ts.
 */

import sharp from 'sharp';
import QRCode from 'qrcode';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';

// ── Canvas & brand tokens ────────────────────────────────────────────────────
const W = 1179;
const H = 2556;

const LINEN = '#faf7f2';
const SAGE = '#7a8b7b';
const BLUSH = '#e8c5c8';
const GOLD = '#d4af37';
const INK = '#2c2825';

export const SITE_URL = 'https://www.fiorevera.hu';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const ASSETS = path.join(__dirname, '../../public/assets/lockscreen');
export const VARIANTS_DIR = path.join(ASSETS, 'variants');

// ── Source geometry ──────────────────────────────────────────────────────────
interface Rect {
  left: number;
  top: number;
  width: number;
  height: number;
}

/** Region of wreath-source.jpg (700×667, already cropped to the painted wreath). */
const WREATH_CROP: Rect = { left: 0, top: 0, width: 700, height: 667 };
/** The thin ornamental frame painted inside the wreath, in crop coordinates. */
const WREATH_BAND: Rect = { left: 153, top: 140, width: 377, height: 370 };

interface FrameSpec {
  file: string;
  outer: Rect; // bounding box of the gold ring in the source
  aperture: Rect; // inner opening in the source
  softIn: number;
  softOut: number;
}

const FRAMES: Record<'gold' | 'ornate' | 'filigree', FrameSpec> = {
  gold: {
    file: 'frame-gold.jpg',
    outer: { left: 130, top: 130, width: 772, height: 772 },
    aperture: { left: 232, top: 232, width: 566, height: 566 },
    softIn: 28,
    softOut: 70,
  },
  ornate: {
    file: 'ornate-frame.jpg',
    outer: { left: 83, top: 84, width: 858, height: 856 },
    aperture: { left: 248, top: 248, width: 532, height: 532 },
    softIn: 24,
    softOut: 64,
  },
  filigree: {
    file: 'delicate-filigree-frame.jpg',
    outer: { left: 88, top: 92, width: 873, height: 850 },
    aperture: { left: 229, top: 216, width: 585, height: 596 },
    softIn: 22,
    softOut: 60,
  },
};

// ── Raw pixel helpers ────────────────────────────────────────────────────────
interface RawRgba {
  data: Buffer;
  width: number;
  height: number;
}

/**
 * Chroma key: max-channel distance from the backdrop → alpha through a soft
 * ramp. With `despill` the colour of semi-transparent edge pixels is
 * decontaminated from the backdrop so no cream/white fringe shows on dark or
 * saturated backgrounds.
 */
function keyBackdrop(
  img: RawRgba,
  backdrop: [number, number, number],
  softIn: number,
  softOut: number,
  despill = false,
): Buffer {
  const out = Buffer.from(img.data);
  for (let i = 0; i < out.length; i += 4) {
    const d = Math.max(
      Math.abs(out[i] - backdrop[0]),
      Math.abs(out[i + 1] - backdrop[1]),
      Math.abs(out[i + 2] - backdrop[2]),
    );
    const a = Math.min(1, Math.max(0, (d - softIn) / (softOut - softIn)));
    out[i + 3] = Math.round(a * 255);
    if (despill && a > 0 && a < 1) {
      // Pull the edge colour away from the backdrop. The correction is capped so
      // near-transparent pixels cannot blow out to black/white.
      const f = Math.min(1.5, (1 - a) / a);
      for (let c = 0; c < 3; c++) {
        const v = out[i + c] + (out[i + c] - backdrop[c]) * f;
        out[i + c] = Math.round(Math.min(255, Math.max(0, v)));
      }
    }
  }
  return out;
}

function medianColour(img: RawRgba, block: number): [number, number, number] {
  const ch: number[][] = [[], [], []];
  for (let y = 0; y < block; y++) {
    for (let x = 0; x < block; x++) {
      const i = (y * img.width + x) * 4;
      ch[0].push(img.data[i]);
      ch[1].push(img.data[i + 1]);
      ch[2].push(img.data[i + 2]);
    }
  }
  const median = (arr: number[]): number => arr.sort((a, b) => a - b)[Math.floor(arr.length / 2)];
  return [median(ch[0]), median(ch[1]), median(ch[2])];
}

async function loadRaw(src: string, region?: sharp.Region): Promise<RawRgba> {
  let pipeline = sharp(src);
  if (region) pipeline = pipeline.extract(region);
  const { data, info } = await pipeline.ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  return { data, width: info.width, height: info.height };
}

function rawToSharp(raw: Buffer, width: number, height: number): sharp.Sharp {
  return sharp(raw, { raw: { width, height, channels: 4 } });
}

// ── Layers ───────────────────────────────────────────────────────────────────
interface Layer {
  png: Buffer;
  width: number;
  height: number;
}

async function toLayer(pipeline: sharp.Sharp): Promise<Layer> {
  const { data, info } = await pipeline.png().toBuffer({ resolveWithObject: true });
  return { png: data, width: info.width, height: info.height };
}

/**
 * Keys the painted wreath for use on non-paper backgrounds.
 *
 * A plain colour-distance key fails here: the palest petal highlights are as
 * light as the paper, so they would turn transparent and show the background
 * through the roses. Instead:
 *   1. flood-fill paper from the crop border (and from a ring just outside the
 *      painted inner band, so the mat between band and flowers clears too) at
 *      a tight tolerance, so only paper connected to those seeds is background;
 *   2. close concavities of the foreground, but accept a filled pixel only
 *      where its surroundings are pink (a petal), never between leaves;
 *   3. keep a soft one-pixel ramp on the outer edge.
 */
function keyWreath(img: RawRgba, paper: [number, number, number]): Buffer {
  const { width: w, height: h } = img;
  const n = w * h;
  const out = Buffer.from(img.data);
  const floodTolerance = 18;
  const closeRadius = 12;

  const dist = new Float32Array(n);
  for (let p = 0; p < n; p++) {
    const i = p * 4;
    dist[p] = Math.max(
      Math.abs(out[i] - paper[0]),
      Math.abs(out[i + 1] - paper[1]),
      Math.abs(out[i + 2] - paper[2]),
    );
  }

  // 1. background = paper connected to the border
  const bg = new Uint8Array(n);
  const stack: number[] = [];
  for (let x = 0; x < w; x++) stack.push(x, (h - 1) * w + x);
  for (let y = 0; y < h; y++) stack.push(y * w, y * w + w - 1);
  const b = WREATH_BAND;
  for (let y = b.top - 14; y < b.top + b.height + 14; y++) {
    for (let x = b.left - 14; x < b.left + b.width + 14; x++) {
      if (x < 0 || y < 0 || x >= w || y >= h) continue;
      const dx = Math.max(b.left - x, x - (b.left + b.width - 1), 0);
      const dy = Math.max(b.top - y, y - (b.top + b.height - 1), 0);
      const ring = Math.max(dx, dy);
      if (ring >= 8 && ring <= 14) stack.push(y * w + x);
    }
  }
  while (stack.length > 0) {
    const p = stack.pop()!;
    if (bg[p] || dist[p] >= floodTolerance) continue;
    bg[p] = 1;
    const x = p % w;
    const y = (p - x) / w;
    if (x > 0) stack.push(p - 1);
    if (x < w - 1) stack.push(p + 1);
    if (y > 0) stack.push(p - w);
    if (y < h - 1) stack.push(p + w);
  }
  const fg = new Uint8Array(n);
  for (let p = 0; p < n; p++) fg[p] = bg[p] ? 0 : 1;

  // 2. pink-gated closing
  const morph = (src: Uint8Array, dilate: boolean): Uint8Array => {
    const pass = (input: Uint8Array, horizontal: boolean): Uint8Array => {
      const dst = new Uint8Array(n);
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          let v = dilate ? 0 : 1;
          for (let k = -closeRadius; k <= closeRadius; k++) {
            const xx = horizontal ? x + k : x;
            const yy = horizontal ? y : y + k;
            if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
            const s = input[yy * w + xx];
            if (dilate ? s === 1 : s === 0) {
              v = dilate ? 1 : 0;
              break;
            }
          }
          dst[y * w + x] = v;
        }
      }
      return dst;
    };
    return pass(pass(src, true), false);
  };
  const closed = morph(morph(fg, true), false);
  const isPink = (i: number): boolean => out[i] - out[i + 1] > 22 && out[i] > 150 && out[i] - out[i + 2] > 30;
  const solid = Uint8Array.from(fg);
  for (let p = 0; p < n; p++) {
    if (!(closed[p] && bg[p])) continue;
    const x = p % w;
    const y = (p - x) / w;
    let pink = 0;
    let total = 0;
    let sr = 0;
    let sg = 0;
    let sb = 0;
    for (let dy = -closeRadius; dy <= closeRadius; dy += 2) {
      for (let dx = -closeRadius; dx <= closeRadius; dx += 2) {
        const xx = x + dx;
        const yy = y + dy;
        if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
        const q = yy * w + xx;
        if (!fg[q]) continue;
        total++;
        const i = q * 4;
        if (isPink(i)) {
          pink++;
          sr += out[i];
          sg += out[i + 1];
          sb += out[i + 2];
        }
      }
    }
    if (total > 0 && pink / total > 0.55) {
      solid[p] = 1;
      const i = p * 4;
      out[i] = Math.round((out[i] + sr / pink) / 2);
      out[i + 1] = Math.round((out[i + 1] + sg / pink) / 2);
      out[i + 2] = Math.round((out[i + 2] + sb / pink) / 2);
    }
  }

  // 3. alpha: opaque inside, soft ramp on the boundary ring
  for (let p = 0; p < n; p++) {
    const i = p * 4;
    if (!solid[p]) {
      out[i + 3] = 0;
      continue;
    }
    const x = p % w;
    const y = (p - x) / w;
    let onEdge = false;
    for (let dy = -1; dy <= 1 && !onEdge; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        const xx = x + dx;
        const yy = y + dy;
        if (xx < 0 || yy < 0 || xx >= w || yy >= h) continue;
        if (!solid[yy * w + xx]) {
          onEdge = true;
          break;
        }
      }
    }
    const ramp = Math.min(1, Math.max(0, (dist[p] - 14) / 32));
    out[i + 3] = onEdge ? Math.round(Math.max(0.45, ramp) * 255) : 255;
  }
  return out;
}

/** Painted wreath keyed off its cream paper. `flop` mirrors it horizontally. */
async function wreathLayer(scale: number, flop = false): Promise<Layer> {
  const raw = await loadRaw(path.join(ASSETS, 'wreath-source.jpg'), WREATH_CROP);
  const paper = medianColour(raw, 24);
  const keyed = keyWreath(raw, paper);
  // Stray petal fragments entering the crop at its top-right corner.
  for (let y = 0; y < 44; y++) {
    for (let x = 540; x < raw.width; x++) keyed[(y * raw.width + x) * 4 + 3] = 0;
  }
  let pipeline = rawToSharp(keyed, raw.width, raw.height).resize(Math.round(raw.width * scale), null, {
    kernel: 'lanczos3',
  });
  if (flop) pipeline = pipeline.flop();
  return toLayer(pipeline);
}

interface FrameLayer extends Layer {
  /** Aperture rectangle in the rendered layer's own coordinates. */
  aperture: Rect;
}

/**
 * Keys a photographed frame off its backdrop, clears the aperture (mat/bevel)
 * and the cast shadow outside the ring, and scales it so that the rendered
 * outer width is `outerWidth` and the rendered aperture is square.
 */
async function frameLayer(spec: FrameSpec, outerWidth: number): Promise<FrameLayer> {
  const margin = 10;
  const region: sharp.Region = {
    left: spec.outer.left - margin,
    top: spec.outer.top - margin,
    width: spec.outer.width + margin * 2,
    height: spec.outer.height + margin * 2,
  };
  const raw = await loadRaw(path.join(ASSETS, spec.file), region);
  const backdrop = medianColour(raw, 8);
  const keyed = keyBackdrop(raw, backdrop, spec.softIn, spec.softOut, true);

  const apLeft = spec.aperture.left - region.left;
  const apTop = spec.aperture.top - region.top;
  for (let y = 0; y < raw.height; y++) {
    for (let x = 0; x < raw.width; x++) {
      const insideAperture =
        x >= apLeft && x < apLeft + spec.aperture.width && y >= apTop && y < apTop + spec.aperture.height;
      const outsideRing =
        x < margin - 4 || y < margin - 4 || x >= margin + spec.outer.width + 4 || y >= margin + spec.outer.height + 4;
      if (insideAperture || outsideRing) keyed[(y * raw.width + x) * 4 + 3] = 0;
    }
  }

  const sx = outerWidth / spec.outer.width;
  const sy = sx * (spec.aperture.width / spec.aperture.height);
  const width = Math.round(raw.width * sx);
  const height = Math.round(raw.height * sy);
  const layer = await toLayer(
    rawToSharp(keyed, raw.width, raw.height).resize(width, height, { kernel: 'lanczos3', fit: 'fill' }),
  );
  const apSize = Math.round(spec.aperture.width * sx);
  return {
    ...layer,
    aperture: { left: Math.round(apLeft * sx), top: Math.round(apTop * sy), width: apSize, height: apSize },
  };
}

async function badgeLayer(width: number): Promise<Layer> {
  return toLayer(sharp(path.join(ASSETS, 'logo-badge.jpg')).resize(width, width, { fit: 'inside' }));
}

// ── SVG pieces ───────────────────────────────────────────────────────────────
function frameShadowSvg(width: number, height: number, opacity = 0.32, blur = 18): Buffer {
  const pad = 80;
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width + pad * 2}" height="${height + pad * 2}">` +
      `<defs><filter id="b" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="${blur}"/></filter></defs>` +
      `<rect x="${pad}" y="${pad}" width="${width}" height="${height}" fill="${INK}" opacity="${opacity}" filter="url(#b)"/>` +
      `</svg>`,
  );
}

function glowSvg(size: number, colour: string, opacity: number): Buffer {
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">` +
      `<defs><radialGradient id="g" cx="50%" cy="50%" r="50%">` +
      `<stop offset="0%" stop-color="${colour}" stop-opacity="${opacity}"/>` +
      `<stop offset="55%" stop-color="${colour}" stop-opacity="${opacity * 0.45}"/>` +
      `<stop offset="100%" stop-color="${colour}" stop-opacity="0"/>` +
      `</radialGradient></defs>` +
      `<rect width="${size}" height="${size}" fill="url(#g)"/></svg>`,
  );
}

/** Opaque card (linen by default) used as a QR mat / badge disc. */
function cardSvg(width: number, height: number, radius: number, fill = LINEN): Buffer {
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">` +
      `<rect width="${width}" height="${height}" rx="${radius}" ry="${radius}" fill="${fill}"/></svg>`,
  );
}

function qrSvg(url: string, size: number): Buffer {
  const qr = QRCode.create(url, { errorCorrectionLevel: 'H' });
  const n = qr.modules.size;
  const quiet = 2;
  const cell = size / (n + quiet * 2);
  const rects: string[] = [];
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      if (!qr.modules.get(row, col)) continue;
      const x = (quiet + col) * cell;
      const y = (quiet + row) * cell;
      rects.push(
        `<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${(cell + 0.3).toFixed(2)}" height="${(cell + 0.3).toFixed(2)}"/>`,
      );
    }
  }
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">` +
      `<rect width="${size}" height="${size}" fill="${LINEN}"/>` +
      `<g fill="${INK}" shape-rendering="crispEdges">${rects.join('')}</g></svg>`,
  );
}

const grainDefs =
  `<filter id="grain"><feTurbulence type="fractalNoise" baseFrequency="0.8" numOctaves="2" seed="7" stitchTiles="stitch"/>` +
  `<feColorMatrix type="saturate" values="0"/></filter>`;

function backgroundSvg(body: string, defs = ''): Buffer {
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><defs>${grainDefs}${defs}</defs>${body}` +
      `<rect width="${W}" height="${H}" filter="url(#grain)" opacity="0.05"/></svg>`,
  );
}

// ── Composition helpers ──────────────────────────────────────────────────────
type Overlay = sharp.OverlayOptions;

/** Clips a layer to the canvas and returns the overlay (sharp refuses oversize inputs). */
async function place(layer: Layer, left: number, top: number, blend?: sharp.Blend): Promise<Overlay | null> {
  const x0 = Math.max(0, left);
  const y0 = Math.max(0, top);
  const x1 = Math.min(W, left + layer.width);
  const y1 = Math.min(H, top + layer.height);
  if (x1 <= x0 || y1 <= y0) return null;
  let png = layer.png;
  if (x0 !== left || y0 !== top || x1 - x0 !== layer.width || y1 - y0 !== layer.height) {
    png = await sharp(layer.png)
      .extract({ left: x0 - left, top: y0 - top, width: x1 - x0, height: y1 - y0 })
      .png()
      .toBuffer();
  }
  const overlay: Overlay = { input: png, left: x0, top: y0 };
  if (blend) overlay.blend = blend;
  return overlay;
}

interface FramedQr {
  overlays: Overlay[];
  qrSize: number;
}

/**
 * Frame + QR centred at (cx, cy). The QR overlaps a few px under the frame lip
 * so no seam shows. Optional linen card under the frame (for openwork frames).
 */
async function framedQr(
  frame: FrameLayer,
  cx: number,
  cy: number,
  url: string,
  opts: { shadow?: { opacity: number; blur: number; dx: number; dy: number }; card?: number } = {},
): Promise<FramedQr> {
  const frameLeft = Math.round(cx - frame.width / 2);
  const frameTop = Math.round(cy - frame.height / 2);
  const overlays: Overlay[] = [];

  if (opts.shadow) {
    const pad = 80;
    const shadow = await toLayer(
      sharp(frameShadowSvg(frame.width - 20, frame.height - 20, opts.shadow.opacity, opts.shadow.blur)),
    );
    const o = await place(shadow, frameLeft + 10 - pad + opts.shadow.dx, frameTop + 10 - pad + opts.shadow.dy, 'multiply');
    if (o) overlays.push(o);
  }
  if (opts.card !== undefined) {
    const inset = opts.card;
    const card = await toLayer(sharp(cardSvg(frame.width - inset * 2, frame.height - inset * 2, 4)));
    const o = await place(card, frameLeft + inset, frameTop + inset);
    if (o) overlays.push(o);
  }

  const overlap = 8;
  const qrSize = frame.aperture.width + overlap * 2;
  const qr = await toLayer(sharp(qrSvg(url, qrSize)));
  const qrO = await place(qr, frameLeft + frame.aperture.left - overlap, frameTop + frame.aperture.top - overlap);
  if (qrO) overlays.push(qrO);

  const frameO = await place(frame, frameLeft, frameTop);
  if (frameO) overlays.push(frameO);
  return { overlays, qrSize };
}

async function render(outputPath: string, background: Buffer, overlays: (Overlay | null)[], qrSize: number): Promise<void> {
  fs.mkdirSync(path.dirname(outputPath), { recursive: true });
  await sharp(background)
    .composite(overlays.filter((o): o is Overlay => o !== null))
    .png({ compressionLevel: 9 })
    .toFile(outputPath);
  console.log(`✅ ${path.relative(process.cwd(), outputPath)} (${W}×${H}); QR ${qrSize}px`);
}

// ── Ink editorial (shipped final) ───────────────────────────────────────────────────────
export async function renderInkEditorial(out: string, url = SITE_URL): Promise<void> {
  const centreY = 1330;
  const background = backgroundSvg(
    `<rect width="${W}" height="${H}" fill="${INK}"/>` +
      `<ellipse cx="${W / 2}" cy="${centreY}" rx="820" ry="760" fill="url(#warm)"/>`,
    `<radialGradient id="warm" cx="50%" cy="50%" r="50%">` +
      `<stop offset="0%" stop-color="#4a3f38" stop-opacity="0.9"/><stop offset="100%" stop-color="#4a3f38" stop-opacity="0"/>` +
      `</radialGradient>`,
  );

  const wreath = await wreathLayer(2.0);
  const frame = await frameLayer(FRAMES.ornate, 900);
  const glow = await toLayer(sharp(glowSvg(1500, GOLD, 0.22)));
  const badge = await badgeLayer(280);
  const disc = await toLayer(sharp(cardSvg(324, 324, 162)));
  const discShadow = await toLayer(sharp(frameShadowSvg(324, 324, 0.5, 14)));

  const { overlays, qrSize } = await framedQr(frame, W / 2, centreY, url, {
    shadow: { opacity: 0.55, blur: 22, dx: 0, dy: 22 },
  });

  const badgeY = 2010;
  await render(
    out,
    background,
    [
      await place(glow, Math.round(W / 2 - 750), centreY - 750, 'screen'),
      await place(wreath, Math.round(W / 2 - wreath.width / 2), Math.round(centreY + 10 - wreath.height / 2)),
      ...overlays,
      await place(discShadow, Math.round(W / 2 - 162 - 80), badgeY - 22 - 80 + 10, 'multiply'),
      await place(disc, Math.round(W / 2 - 162), badgeY - 22),
      await place(badge, Math.round(W / 2 - 140), badgeY, 'multiply'),
    ],
    qrSize,
  );
}

// ── Linen classic (previous final) ───────────────────────────────────────────
export async function renderLinenClassic(out: string, url = SITE_URL): Promise<void> {
  const wreathCentreY = 1350;
  const frameCentreY = wreathCentreY - 4;
  const background = backgroundSvg(
    `<rect width="${W}" height="${H}" fill="${LINEN}"/>` +
      `<ellipse cx="${W / 2}" cy="${wreathCentreY}" rx="700" ry="640" fill="url(#blushGlow)"/>`,
    `<radialGradient id="blushGlow" cx="50%" cy="50%" r="50%">` +
      `<stop offset="0%" stop-color="${BLUSH}" stop-opacity="0.30"/>` +
      `<stop offset="100%" stop-color="${BLUSH}" stop-opacity="0"/></radialGradient>`,
  );

  const wreath = await wreathLayer(1.8);
  const frame = await frameLayer(FRAMES.gold, 760);
  const badgeWidth = 300;
  const badge = await badgeLayer(badgeWidth);

  const { overlays, qrSize } = await framedQr(frame, W / 2, frameCentreY, url, {
    shadow: { opacity: 0.32, blur: 18, dx: 4, dy: 18 },
  });

  await render(
    out,
    background,
    [
      await place(wreath, Math.round(W / 2 - wreath.width / 2), Math.round(wreathCentreY - wreath.height / 2)),
      ...overlays,
      await place(badge, Math.round((W - badgeWidth) / 2), 1985, 'multiply'),
    ],
    qrSize,
  );
}

// ── Sage garland ────────────────────────────────────────────────────────
export async function renderSageGarland(out: string, url = SITE_URL): Promise<void> {
  const centreY = 1640;
  const background = backgroundSvg(
    `<rect width="${W}" height="${H}" fill="url(#sage)"/>`,
    `<linearGradient id="sage" x1="0" y1="0" x2="0" y2="1">` +
      `<stop offset="0%" stop-color="#9aa697"/><stop offset="100%" stop-color="${SAGE}"/></linearGradient>`,
  );

  const wreath = await wreathLayer(1.9, true);
  const frame = await frameLayer(FRAMES.filigree, 840);
  const badge = await badgeLayer(240);
  const disc = await toLayer(sharp(cardSvg(280, 280, 140)));
  const discShadow = await toLayer(sharp(frameShadowSvg(280, 280, 0.35, 14)));

  const { overlays, qrSize } = await framedQr(frame, W / 2, centreY, url, {
    shadow: { opacity: 0.38, blur: 20, dx: 0, dy: 20 },
    card: 40, // inset past the frame's slightly slanted outer edge
  });

  const badgeY = 1040;
  await render(
    out,
    background,
    [
      await place(wreath, Math.round(W / 2 - wreath.width / 2), Math.round(centreY - 10 - wreath.height / 2)),
      ...overlays,
      await place(discShadow, Math.round(W / 2 - 140 - 80), badgeY - 20 - 80 + 10, 'multiply'),
      await place(disc, Math.round(W / 2 - 140), badgeY - 20),
      await place(badge, Math.round(W / 2 - 120), badgeY, 'multiply'),
    ],
    qrSize,
  );
}

// ── Blush minimal ───────────────────────────────────────────────────────
export async function renderBlushMinimal(out: string, url = SITE_URL): Promise<void> {
  const centreY = 1230;
  const background = backgroundSvg(
    `<rect width="${W}" height="${H}" fill="url(#blush)"/>`,
    `<linearGradient id="blush" x1="0" y1="0" x2="0" y2="1">` +
      `<stop offset="0%" stop-color="${BLUSH}"/><stop offset="45%" stop-color="#f3e3e1"/>` +
      `<stop offset="100%" stop-color="${LINEN}"/></linearGradient>`,
  );

  // Only the wreath's left arc is visible: the rest bleeds off the right and
  // bottom edges, so the canvas itself is the crop. The wreath's painted inner
  // frame band starts at crop x≈153, which is kept just past the right edge.
  const wreathScale = 2.8;
  const wreath = await wreathLayer(wreathScale);
  const wreathLeft = W - Math.round(150 * wreathScale);
  const wreathTop = 1120;

  const frame = await frameLayer(FRAMES.gold, 760);
  const badge = await badgeLayer(230);

  const { overlays, qrSize } = await framedQr(frame, 480, centreY, url, {
    shadow: { opacity: 0.3, blur: 18, dx: 4, dy: 18 },
  });

  await render(
    out,
    background,
    [
      await place(wreath, wreathLeft, wreathTop),
      ...overlays,
      await place(badge, 130, 1980, 'multiply'),
    ],
    qrSize,
  );
}
